type Snapshot = {
  readonly node: readonly IRow[];
  readonly node__parent: readonly IRow[];
};

function read_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    node: select_rows(seam, `SELECT "node_id", CASE WHEN json_valid("name") AND json_type("name") = 'object' AND json_type("name", '$.fn') = 'text' AND json_type("name", '$.args') = 'array' THEN json_extract("name", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("name", '$.args')), '') || ')' ELSE "name" END AS "name" FROM "__txt_node" t`, rel_columns.node!, rel_column_types.node!),
    node__parent: select_rows(seam, `SELECT "node_id", "parent_node_id" FROM "node__parent" t`, rel_columns.node__parent!, rel_column_types.node__parent!),
  });
}

type Snapshots = { readonly decoded: Snapshot; readonly stored: Snapshot };

function read_stored_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    node: select_rows(seam, `SELECT "node_id", "name" FROM "node"`, rel_columns.node!, rel_column_types.node!),
    node__parent: select_rows(seam, `SELECT "node_id", "parent_node_id" FROM "node__parent"`, rel_columns.node__parent!, rel_column_types.node__parent!),
  });
}

function read_snapshots(seam: ISqlSeam): Observable<Snapshots> {
  return forkJoin({ decoded: read_snapshot(seam), stored: read_stored_snapshot(seam) });
}

